describe('Product List Display', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.get('#user-name').type('standard_user');
    cy.get('#password').type('secret_sauce');
    cy.get('#login-button').click();
  });

  it('should display exactly 6 product cards', () => {
    cy.get('.inventory_item').should('have.length', 6);
  });

  it('should have non-empty name for each product card', () => {
    cy.get('.inventory_item_name').each(($name) => {
      cy.wrap($name).should('not.be.empty');
    });
  });

  it('should have price starting with $ for each product card', () => {
    cy.get('.inventory_item_price').each(($price) => {
      cy.wrap($price).invoke('text').should('match', /^\$/);
    });
  });
});
